css:
@page {
	size: A4;
	margin: 10mm 12mm 10mm 12mm;
}

* {
	box-sizing: border-box;
}

body {
	font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
	font-size: 9pt;
	color: #333;
	line-height: 1.4;
}

.invoice-wrap {
	max-width: 190mm;
	margin: 0 auto;
}

.invoice-header {
	display: flex;
	justify-content: space-between;
	align-items: flex-start;
	padding-bottom: 8px;
	border-bottom: 3px solid #1a5276;
	margin-bottom: 10px;
}

.company-details h2 {
	margin: 0 0 2px 0;
	font-size: 16pt;
	color: #1a5276;
}

.company-details p {
	margin: 1px 0;
	font-size: 8.5pt;
	color: #555;
}

.invoice-badge {
	text-align: right;
}

.invoice-badge h1 {
	margin: 0;
	font-size: 18pt;
	color: #1a5276;
	letter-spacing: 1px;
}

.invoice-badge .badge-rcm {
	display: inline-block;
	background: #e74c3c;
	color: #fff;
	padding: 2px 10px;
	font-size: 8pt;
	font-weight: bold;
	border-radius: 3px;
	margin-top: 4px;
}

.invoice-badge .badge-sez {
	display: inline-block;
	background: #8e44ad;
	color: #fff;
	padding: 2px 10px;
	font-size: 8pt;
	font-weight: bold;
	border-radius: 3px;
	margin-top: 4px;
}

.invoice-badge .badge-export {
	display: inline-block;
	background: #2980b9;
	color: #fff;
	padding: 2px 10px;
	font-size: 8pt;
	font-weight: bold;
	border-radius: 3px;
	margin-top: 4px;
}

.info-row {
	display: flex;
	justify-content: space-between;
	margin-bottom: 8px;
	gap: 12px;
}

.info-box {
	flex: 1;
	border: 1px solid #ddd;
	border-radius: 4px;
	padding: 8px 10px;
}

.info-box h4 {
	margin: 0 0 4px 0;
	font-size: 8pt;
	color: #1a5276;
	text-transform: uppercase;
	letter-spacing: 0.5px;
	border-bottom: 1px solid #eee;
	padding-bottom: 3px;
}

.info-box p {
	margin: 1px 0;
	font-size: 8.5pt;
}

.info-box .label {
	color: #888;
	font-size: 7.5pt;
}

.info-box .gstin-highlight {
	font-weight: bold;
	color: #1a5276;
}

.info-row-gap {
	display: flex;
	justify-content: space-between;
	margin-bottom: 6px;
	gap: 12px;
}

.info-cell {
	flex: 1;
}

.info-cell .label {
	color: #888;
	font-size: 7.5pt;
}

.info-cell .value {
	color: #333;
	font-size: 9pt;
	font-weight: 500;
}

.items-table {
	width: 100%;
	border-collapse: collapse;
	margin: 8px 0;
	font-size: 8pt;
}

.items-table th {
	background: #1a5276;
	color: #fff;
	padding: 6px 4px;
	text-align: left;
	font-size: 7.5pt;
	text-transform: uppercase;
	letter-spacing: 0.3px;
}

.items-table td {
	padding: 5px 4px;
	border-bottom: 1px solid #eee;
	vertical-align: top;
}

.items-table tr:nth-child(even) td {
	background: #f8f9fa;
}

.items-table .text-right {
	text-align: right;
}

.items-table .text-center {
	text-align: center;
}

.totals-section {
	display: flex;
	justify-content: flex-end;
	margin: 6px 0 10px 0;
}

.totals-table {
	width: 50%;
	border-collapse: collapse;
	font-size: 8.5pt;
}

.totals-table td {
	padding: 3px 8px;
	border-bottom: 1px solid #eee;
}

.totals-table td:last-child {
	text-align: right;
	font-weight: 500;
}

.totals-table .grand-total td {
	font-size: 10pt;
	font-weight: bold;
	color: #1a5276;
	border-top: 2px solid #1a5276;
	padding-top: 5px;
}

.tax-summary {
	width: 100%;
	border-collapse: collapse;
	margin: 4px 0 8px 0;
	font-size: 8pt;
}

.tax-summary th {
	background: #eaf2f8;
	color: #1a5276;
	padding: 5px 8px;
	text-align: left;
	font-size: 7.5pt;
	text-transform: uppercase;
	border-bottom: 2px solid #1a5276;
}

.tax-summary td {
	padding: 4px 8px;
	border-bottom: 1px solid #eee;
}

.tax-summary td:last-child {
	text-align: right;
}

.tax-summary .total-row td {
	font-weight: bold;
	border-top: 2px solid #1a5276;
}

.amount-words {
	margin: 8px 0;
	padding: 6px 10px;
	background: #f0f4f8;
	border-left: 3px solid #1a5276;
	border-radius: 2px;
	font-size: 9pt;
	font-style: italic;
	color: #555;
}

.amount-words strong {
	color: #333;
}

.bottom-section {
	display: flex;
	justify-content: space-between;
	margin-top: 12px;
	padding-top: 8px;
	border-top: 1px solid #ddd;
	gap: 12px;
}

.bottom-left {
	flex: 2;
}

.bottom-right {
	flex: 1;
	text-align: right;
}

.bottom-section h5 {
	margin: 0 0 3px 0;
	font-size: 8pt;
	color: #1a5276;
	text-transform: uppercase;
}

.bottom-section p {
	margin: 1px 0;
	font-size: 8pt;
	color: #555;
}

.signature-area {
	margin-top: 16px;
	padding-top: 10px;
}

.signature-area .sign-line {
	width: 180px;
	border-top: 1px solid #333;
	margin-left: auto;
	padding-top: 4px;
	text-align: center;
	font-size: 8pt;
	color: #555;
}
